/**
 * Exo GEMVER driver: mirrors PolyBench/C gemver.c but calls the Exo-generated kernel.
 *
 * Original authors:
 *   Louis-Noel Pouchet <pouchet.ohio-state.edu>
 *   Tomofumi Yuki <tomofumi.yuki.fr>
 *
 * Web address: http://polybench.sourceforge.net
 */
/* gemver.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "gemver.h"

/* Include the Exo-generated kernel header. */
#include "generated/gemver/gemver.h"


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE *alpha,
		 DATA_TYPE *beta,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		 DATA_TYPE POLYBENCH_1D(u1,N,n),
		 DATA_TYPE POLYBENCH_1D(v1,N,n),
		 DATA_TYPE POLYBENCH_1D(u2,N,n),
		 DATA_TYPE POLYBENCH_1D(v2,N,n),
		 DATA_TYPE POLYBENCH_1D(w,N,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n),
		 DATA_TYPE POLYBENCH_1D(y,N,n),
		 DATA_TYPE POLYBENCH_1D(z,N,n))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;

  DATA_TYPE fn = (DATA_TYPE)n;

  for (i = 0; i < n; i++)
    {
      u1[i] = i;
      u2[i] = ((i+1)/fn)/2.0;
      v1[i] = ((i+1)/fn)/4.0;
      v2[i] = ((i+1)/fn)/6.0;
      y[i] = ((i+1)/fn)/8.0;
      z[i] = ((i+1)/fn)/9.0;
      x[i] = 0.0;
      w[i] = 0.0;
      for (j = 0; j < n; j++)
        A[i][j] = (DATA_TYPE) (i*j % n) / n;
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(w,N,n))
{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("w");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, w[i]);
  }
  POLYBENCH_DUMP_END("w");
  POLYBENCH_DUMP_FINISH;
}

/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *  # import scheduling primitives (even if unused)
from exo.libs.memories import DRAM

# Square tiles for the 2D loops over A.
# These are compile-time constants chosen to give good cache locality on x64.
TILE_I = 32
TILE_J = 32


@proc
def kernel_gemver(
    n: size,
    alpha: DATA_TYPE,
    beta: DATA_TYPE,
    A: DATA_TYPE[n, n] @ DRAM,
    u1: DATA_TYPE[n] @ DRAM,
    v1: DATA_TYPE[n] @ DRAM,
    u2: DATA_TYPE[n] @ DRAM,
    v2: DATA_TYPE[n] @ DRAM,
    w: DATA_TYPE[n] @ DRAM,
    x: DATA_TYPE[n] @ DRAM,
    y: DATA_TYPE[n] @ DRAM,
    z: DATA_TYPE[n] @ DRAM,
):
    # Phase 1: rank-2 update of A
    #   A := A + u1 v1^T + u2 v2^T
    #
    # We apply 2D tiling over (i, j) to improve cache locality for A and v1/v2.
    # The outer loops iterate over tiles, and the inner loops cover points in
    # each tile. The if-guards correctly handle edge tiles when n is not a
    # multiple of the tile sizes.
    for I in seq(0, (n + TILE_I - 1) / TILE_I):
        for J in seq(0, (n + TILE_J - 1) / TILE_J):
            for i in seq(0, TILE_I):
                if I * TILE_I + i < n:
                    # Keep the row-specific u1[i], u2[i] in scalar temporaries
                    # so they stay in registers across the inner j-loop.
                    u1_i: DATA_TYPE
                    u2_i: DATA_TYPE
                    u1_i = u1[I * TILE_I + i]
                    u2_i = u2[I * TILE_I + i]
                    for j in seq(0, TILE_J):
                        if J * TILE_J + j < n:
                            A[I * TILE_I + i, J * TILE_J + j] = (
                                A[I * TILE_I + i, J * TILE_J + j]
                                + u1_i * v1[J * TILE_J + j]
                                + u2_i * v2[J * TILE_J + j]
                            )

    # Phase 2: x := x + beta * A^T * y
    #
    # Original code:
    #   for i in seq(0, n):
    #       for j in seq(0, n):
    #           x[i] = x[i] + beta * A[j, i] * y[j]
    #
    # This accesses A by columns (j outer, i inner is better for row-major).
    # We interchange the loops conceptually and implement:
    #   for j in [0, n):
    #       t = beta * y[j]
    #       for i in [0, n):
    #           x[i] += A[j, i] * t
    #
    # This preserves the mathematical result x := x + beta * A^T y while:
    #   - Scanning A row-wise (A[j, i] with fixed j, varying i ⇒ unit stride),
    #   - Computing beta * y[j] once per row j (instead of per (i, j) pair).
    for j in seq(0, n):
        t: DATA_TYPE
        t = beta * y[j]
        for i in seq(0, n):
            x[i] = x[i] + A[j, i] * t

    # Phase 3: x := x + z
    # Simple elementwise update; independent across i.
    for i in seq(0, n):
        x[i] = x[i] + z[i]

    # Phase 4: w := w + alpha * A * x
    #
    # Original code:
    #   for i in [0, n):
    #       for j in [0, n):
    #           w[i] += alpha * A[i, j] * x[j]
    #
    # We first precompute a temporary vector
    #   x_scaled[j] = alpha * x[j]
    # so that the inner loop only performs A[i, j] * x_scaled[j] and one
    # accumulation, saving one multiplication by alpha per (i, j).
    #
    # We also tile the (i, j) space, similar to Phase 1, to increase spatial
    # locality over A and x_scaled.
    x_scaled: DATA_TYPE[n] @ DRAM
    for j in seq(0, n):
        x_scaled[j] = alpha * x[j]

    for I in seq(0, (n + TILE_I - 1) / TILE_I):
        for J in seq(0, (n + TILE_J - 1) / TILE_J):
            for i in seq(0, TILE_I):
                if I * TILE_I + i < n:
                    for j in seq(0, TILE_J):
                        if J * TILE_J + j < n:
                            w[I * TILE_I + i] = (
                                w[I * TILE_I + i]
                                + A[I * TILE_I + i, J * TILE_J + j]
                                * x_scaled[J * TILE_J + j]
                            )
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(u1, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(v1, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(u2, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(v2, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(w,  DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(x,  DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y,  DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(z,  DATA_TYPE, N, n);

  /* Initialize array(s). */
  init_array (n, &alpha, &beta,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(u1),
	      POLYBENCH_ARRAY(v1),
	      POLYBENCH_ARRAY(u2),
	      POLYBENCH_ARRAY(v2),
	      POLYBENCH_ARRAY(w),
	      POLYBENCH_ARRAY(x),
	      POLYBENCH_ARRAY(y),
	      POLYBENCH_ARRAY(z));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten PolyBench views to raw pointers. */
  kernel_gemver(/*ctxt=*/NULL, n,
                (DATA_TYPE*)&alpha,
                (DATA_TYPE*)&beta,
                (DATA_TYPE*)POLYBENCH_ARRAY(A),
                (DATA_TYPE*)POLYBENCH_ARRAY(u1),
                (DATA_TYPE*)POLYBENCH_ARRAY(v1),
                (DATA_TYPE*)POLYBENCH_ARRAY(u2),
                (DATA_TYPE*)POLYBENCH_ARRAY(v2),
                (DATA_TYPE*)POLYBENCH_ARRAY(w),
                (DATA_TYPE*)POLYBENCH_ARRAY(x),
                (DATA_TYPE*)POLYBENCH_ARRAY(y),
                (DATA_TYPE*)POLYBENCH_ARRAY(z));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(w)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(u1);
  POLYBENCH_FREE_ARRAY(v1);
  POLYBENCH_FREE_ARRAY(u2);
  POLYBENCH_FREE_ARRAY(v2);
  POLYBENCH_FREE_ARRAY(w);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(y);
  POLYBENCH_FREE_ARRAY(z);

  return 0;
}
