from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Baseline kernel that directly mirrors the original PolyBench GEMVER
# computation. This is kept simple and obviously correct; all performance
# optimizations are expressed below as explicit scheduling transforms.
@proc
def kernel_gemver_base(
    n: size,
    alpha: DATA_TYPE,
    beta: DATA_TYPE,
    A: DATA_TYPE[n, n] @ DRAM,
    u1: DATA_TYPE[n] @ DRAM,
    v1: DATA_TYPE[n] @ DRAM,
    u2: DATA_TYPE[n] @ DRAM,
    v2: DATA_TYPE[n] @ DRAM,
    w: DATA_TYPE[n] @ DRAM,
    x: DATA_TYPE[n] @ DRAM,
    y: DATA_TYPE[n] @ DRAM,
    z: DATA_TYPE[n] @ DRAM,
):
    # Phase 1: rank‑2 update of A
    for i in seq(0, n):
        for j in seq(0, n):
            A[i, j] = A[i, j] + u1[i] * v1[j] + u2[i] * v2[j]

    # Phase 2: x := x + beta * A^T * y
    for i in seq(0, n):
        for j in seq(0, n):
            x[i] = x[i] + beta * A[j, i] * y[j]

    # Phase 3: x := x + z
    for i in seq(0, n):
        x[i] = x[i] + z[i]

    # Phase 4: w := w + alpha * A * x
    for i in seq(0, n):
        for j in seq(0, n):
            w[i] = w[i] + alpha * A[i, j] * x[j]


# ---------------------------------------------------------------------------
# Scheduling: build an optimized version of the kernel.
#
# We:
#   * Improve cache locality for the A^T * y phase by interchanging its i/j
#     loops so that A is traversed row‑wise (contiguous in memory).
#   * Parallelize the outer i‑loops of phases 1, 3, and 4. These loops work
#     on disjoint rows / elements, so iterations are independent and safe
#     to parallelize.
#
# All transformations preserve the mathematical computation; only the
# execution order of independent iterations is changed.
# ---------------------------------------------------------------------------

kernel_gemver_sched = kernel_gemver_base

# 1) Improve locality of x update (phase 2) by traversing A row‑major.
#    We reorder the second (i,j) nest from:
#        for i:
#          for j:
#            x[i] += beta * A[j, i] * y[j]
#    to:
#        for j:
#          for i:
#            x[i] += beta * A[j, i] * y[j]
#    For each fixed i, the sequence of j values is still 0..n‑1, so the
#    per‑element reduction order on x[i] is unchanged (bit‑identical).
kernel_gemver_sched = reorder_loops(kernel_gemver_sched, "i j #1")

# 2) Parallelize outer i‑loops of phases 1, 3, and 4.
#    These loops have no cross‑iteration dependencies:
#      * Phase 1: each i writes a distinct row A[i, :]
#      * Phase 3: each i updates only x[i]
#      * Phase 4: each i accumulates into its own w[i] using row A[i, :]
#    Exo’s parallel analysis verifies legality and the backend lowers
#    these to OpenMP parallel loops on a multicore CPU.
kernel_gemver_sched = parallelize_loop(kernel_gemver_sched, "i #0")  # phase 1 i-loop
kernel_gemver_sched = parallelize_loop(kernel_gemver_sched, "i #2")  # phase 3 i-loop
kernel_gemver_sched = parallelize_loop(kernel_gemver_sched, "i #3")  # phase 4 i-loop

# 3) Expose the scheduled kernel under the name used by the C driver.
kernel_gemver = rename(kernel_gemver_sched, "kernel_gemver")
EXO END
*/


