def kernel_gemver_impl(
    n: size,
    alpha: DATA_TYPE,
    beta: DATA_TYPE,
    A: DATA_TYPE[n, n] @ DRAM,
    u1: DATA_TYPE[n] @ DRAM,
    v1: DATA_TYPE[n] @ DRAM,
    u2: DATA_TYPE[n] @ DRAM,
    v2: DATA_TYPE[n] @ DRAM,
    w: DATA_TYPE[n] @ DRAM,
    x: DATA_TYPE[n] @ DRAM,
    y: DATA_TYPE[n] @ DRAM,
    z: DATA_TYPE[n] @ DRAM,
):
    #
    # Phase 1: rank-2 update on A
    #   A := A + u1 v1^T + u2 v2^T
    # Row-major A, so we keep j (column) as the innermost loop.
    #
    for i in seq(0, n):
        for j in seq(0, n):
            A[i, j] = A[i, j] + u1[i] * v1[j] + u2[i] * v2[j]

    #
    # Phase 2: x := x + beta * A^T y
    # Original PolyBench/Exo structure:
    #   for i:
    #       for j:
    #           x[i] += beta * A[j, i] * y[j]
    #
    # This directly matches the original semantics; we will later
    # parallelize across i while keeping this simple, clear form.
    #
    for i in seq(0, n):
        for j in seq(0, n):
            x[i] += beta * A[j, i] * y[j]

    #
    # Phase 3: x := x + z
    # Simple elementwise SAXPY-like update.
    #
    for i in seq(0, n):
        x[i] += z[i]

    #
    # Phase 4: w := w + alpha * A x
    # Standard GEMV:
    #   for i:
